// The plugin against a fake facilitator MCP on 127.0.0.1, started by this test: an HTTP server that
// lists the facilitator's eight tools exactly as POST /mcp lists them (test/fixtures/facilitator-tools.json,
// generated by src/mcp.rs), answers tools/call like the facilitator (JSON, not an SSE frame) and, like
// rmcp, refuses with 406 a request whose Accept does not name both application/json and
// text/event-stream. The plugin's fetch is the real one, pointed at this server instead of the
// facilitator's host; nothing else differs from PayBox. What it shows: the plugin's tools/list is
// exactly the reads of the fake's tools/list, each read reaches the fake once and comes back as the
// fake answered, and a payment rail never reaches it.
import { after, before, test } from "node:test";
import assert from "node:assert/strict";
import { createServer, type IncomingMessage, type Server } from "node:http";
import type { AddressInfo } from "node:net";

import { CLASS_META_KEY, READ_CLASS } from "../src/catalogo.ts";
import { ORIGIN } from "../src/facilitator.ts";
import { callTool, deps, facilitatorTools, REAL_FETCH, rpc, text } from "./harness.ts";

const LISTED = facilitatorTools();
const RAILS = ["x402_accepts", "x402_verify", "x402_settle"];

interface Reached {
  method: string;
  name?: string;
  arguments?: unknown;
}

const reached: Reached[] = [];
let server: Server;
let base = "";

/** What the fake answers for a read: a body, as its text block and as structuredContent. */
function answerFor(name: string, args: unknown): Record<string, unknown> {
  const body = { tool: name, arguments: args, source: "fake facilitator" };
  return { content: [{ type: "text", text: JSON.stringify(body) }], structuredContent: body };
}

async function readBody(request: IncomingMessage): Promise<string> {
  const chunks: Buffer[] = [];
  for await (const chunk of request) chunks.push(chunk as Buffer);
  return Buffer.concat(chunks).toString("utf8");
}

before(async () => {
  server = createServer(async (request, response) => {
    const reply = (status: number, body: unknown) => {
      response.writeHead(status, { "content-type": "application/json" });
      response.end(JSON.stringify(body));
    };
    if (request.method !== "POST" || request.url !== "/mcp") return reply(404, { error: "not found" });
    const accept = request.headers.accept ?? "";
    if (!accept.includes("application/json") || !accept.includes("text/event-stream")) {
      return reply(406, { error: "Not Acceptable" });
    }
    const message = JSON.parse(await readBody(request));
    const { id, method, params } = message;
    reached.push({ method, name: params?.name, arguments: params?.arguments });
    if (method === "tools/list") return reply(200, { jsonrpc: "2.0", id, result: { tools: LISTED } });
    if (method === "tools/call") {
      const tool = LISTED.find((t) => t.name === params.name);
      if (!tool) {
        return reply(200, { jsonrpc: "2.0", id, error: { code: -32601, message: `unknown tool: ${params.name}`, data: { tools: LISTED.map((t) => t.name) } } });
      }
      return reply(200, { jsonrpc: "2.0", id, result: answerFor(params.name, params.arguments) });
    }
    return reply(200, { jsonrpc: "2.0", id, error: { code: -32601, message: `unknown method: ${method}` } });
  });
  await new Promise<void>((resolve) => server.listen(0, "127.0.0.1", resolve));
  base = `http://127.0.0.1:${(server.address() as AddressInfo).port}`;
});

after(async () => {
  await new Promise<void>((resolve) => server.close(() => resolve()));
});

/** The real fetch, on the fake instead of the facilitator's host: the only change. */
function toFake(input: string, init: RequestInit): Promise<Response> {
  assert.ok(input.startsWith(`${ORIGIN}/`), input);
  return REAL_FETCH(`${base}${input.slice(ORIGIN.length)}`, init);
}

/** tools/list asked of the fake directly, as any MCP client would. */
async function fakeToolsList(): Promise<Record<string, any>[]> {
  const response = await REAL_FETCH(`${base}/mcp`, {
    method: "POST",
    headers: { "content-type": "application/json", accept: "application/json, text/event-stream" },
    body: JSON.stringify({ jsonrpc: "2.0", id: 7, method: "tools/list", params: {} }),
  });
  assert.equal(response.status, 200);
  return ((await response.json()) as { result: { tools: Record<string, any>[] } }).result.tools;
}

test("against a fake MCP that lists the facilitator's eight tools, tools/list is exactly its reads", async () => {
  const fake = await fakeToolsList();
  assert.equal(fake.length, 8);
  for (const rail of RAILS) assert.ok(fake.some((t) => t.name === rail), `the fake lists ${rail}`);
  reached.length = 0;
  const response = await rpc(deps(toFake), "tools/list");
  assert.equal(response.error, undefined, JSON.stringify(response.error));
  const reads = fake.filter((t) => t._meta?.[CLASS_META_KEY] === READ_CLASS);
  assert.deepEqual(response.result.tools, reads);
  assert.deepEqual(
    response.result.tools.map((t: { name: string }) => t.name),
    ["x402_supported", "x402_networks", "x402_chain_health", "x402_escrow_onchain_state", "x402_durable_evidence"],
  );
  // tools/list is the plugin's own catalog: listing asks the facilitator nothing.
  assert.deepEqual(reached, []);
});

test("each read reaches the fake once, by its name and arguments, and comes back as the fake answered", async () => {
  const cases: [string, Record<string, unknown>][] = [
    ["x402_supported", {}],
    ["x402_networks", {}],
    ["x402_chain_health", { network: "base" }],
    ["x402_escrow_onchain_state", { network: "eip155:8453" }],
    ["x402_durable_evidence", { paymentId: "0xab", document: "receipt" }],
  ];
  for (const [name, args] of cases) {
    reached.length = 0;
    const result = await callTool(deps(toFake), name, args);
    assert.deepEqual(reached, [{ method: "tools/call", name, arguments: args }], name);
    const expected = answerFor(name, args);
    assert.deepEqual(result.content, expected.content, name);
    assert.deepEqual(result.structuredContent, expected.structuredContent, name);
    assert.notEqual(result.isError, true, text(result));
  }
});

test("a payment rail never reaches the fake, whatever the arguments", async () => {
  reached.length = 0;
  for (const name of RAILS) {
    const response = await rpc(deps(toFake), "tools/call", { name, arguments: { paymentPayload: {}, paymentRequirements: {} } });
    assert.equal(response.error?.code, -32602, JSON.stringify(response));
  }
  assert.deepEqual(reached, []);
});

test("the plugin's headers pass the transport's Accept check", async () => {
  const response = await REAL_FETCH(`${base}/mcp`, {
    method: "POST",
    headers: { "content-type": "application/json", accept: "application/json" },
    body: JSON.stringify({ jsonrpc: "2.0", id: 8, method: "tools/list", params: {} }),
  });
  assert.equal(response.status, 406, "the fake refuses what rmcp refuses");
  const result = await callTool(deps(toFake), "x402_networks");
  assert.notEqual(result.isError, true, text(result));
});
